<script lang="ts">
  import { onMount } from "svelte";
  import { invoke, isTauri } from "@tauri-apps/api/core";
  import { Building2, ExternalLink, FileSearch, RefreshCw, ShieldCheck } from "lucide-svelte";
  type Filing = { cik:number; accessionNumber:string; form:string; filingDate:string; reportDate:string|null; primaryDocument:string|null; sourceUrl:string };
  type Persistence = { state:"persisted"|"policy_required"|"failed"; inserted:number; unchanged:number; totalObservations:number; retainedPayloads:boolean; policyVersion:number|null; message:string };
  type Snapshot = { provider:string; retrievedAt:string; cik:number; filings:Filing[]; evidence:string; persistence:Persistence };
  const issuers = [[320193,"Apple"],[1045810,"NVIDIA"],[789019,"Microsoft"],[1652044,"Alphabet"],[1018724,"Amazon"],[1326801,"Meta"],[1318605,"Tesla"]] as const;
  let cik = $state(320193); let query = $state(""); let form = $state("material"); let snapshot = $state<Snapshot|null>(null); let loading = $state(false); let error = $state<string|null>(null);
  const forms = $derived(form === "material" ? ["8-K","10-K","10-Q","4","13F-HR"] : form === "all" ? [] : [form]);
  const filtered = $derived((snapshot?.filings ?? []).filter(row => `${row.form} ${row.accessionNumber} ${row.primaryDocument ?? ""}`.toLowerCase().includes(query.toLowerCase())));
  async function load() { if(!isTauri()){error="Native desktop runtime required.";return} loading=true;error=null;try{snapshot=await invoke<Snapshot>("get_filing_summaries",{cik,forms})}catch(cause){snapshot=null;error=cause instanceof Error?cause.message:String(cause)}finally{loading=false} }
  onMount(()=>{void load()});
</script>
<svelte:head><title>Institutional intelligence · PRISMATIK</title></svelte:head>
<main class="terminal">
  <header><div><p class="eyebrow">INSTITUTIONAL EVIDENCE</p><h1>Filings intelligence</h1><p class="lede">Accession-level SEC submissions from a connected EDGAR session, preserving filing dates, report periods, documents, and official source links.</p></div><div class:live={!!snapshot} class="mode"><i></i><span>{snapshot?"SEC EDGAR LIVE":"NO FILING INPUT"}</span><strong>{snapshot?new Date(snapshot.retrievedAt).toLocaleTimeString():"Connect provider"}</strong></div></header>
  <section class="controls"><label><span>Issuer / CIK</span><select bind:value={cik} onchange={load}>{#each issuers as issuer}<option value={issuer[0]}>{issuer[1]} · {issuer[0]}</option>{/each}</select></label><label><span>Form scope</span><select bind:value={form} onchange={load}><option value="material">Material set</option><option value="all">All recent</option><option value="10-K">10-K annual</option><option value="10-Q">10-Q quarterly</option><option value="8-K">8-K events</option><option value="4">Form 4 insiders</option><option value="13F-HR">13F holdings</option></select></label><label class="search"><span>Filter retrieved evidence</span><input bind:value={query} placeholder="Form, accession, document…"/></label><button onclick={load} disabled={loading}><RefreshCw size={14} class={loading ? "spin" : ""}/>{loading?"Retrieving":"Refresh"}</button></section>
  {#if error}<section class="notice"><FileSearch size={18}/><div><strong>Filing evidence unavailable</strong><p>{error}</p></div><a href="/workspace/integrations">Open integrations</a></section>{/if}
  {#if snapshot && snapshot.persistence.state !== "persisted"}<section class="notice"><ShieldCheck size={18}/><div><strong>Live data is not retained</strong><p>{snapshot.persistence.message}</p></div><a href="/workspace/integrations">Review source policy</a></section>{/if}
  <section class="metrics"><article><span>Issuer CIK</span><strong>{snapshot?.cik ?? cik}</strong><small>SEC canonical identifier</small></article><article><span>Retrieved filings</span><strong>{snapshot?.filings.length ?? 0}</strong><small>{form === "all" ? "All recent forms" : forms.join(" · ")}</small></article><article><span>Latest filing</span><strong>{snapshot?.filings[0]?.filingDate ?? "—"}</strong><small>{snapshot?.filings[0]?.form ?? "Awaiting evidence"}</small></article><article><span>Evidence route</span><strong>{snapshot?"VERIFIED":"CLOSED"}</strong><small>{snapshot?"Official accession links":"No fixture fallback"}</small></article></section>
  <section class="panel"><div class="panel-head"><div><span>RECENT SUBMISSIONS LEDGER</span><strong>{filtered.length} visible records</strong></div><ShieldCheck size={16}/></div>
    {#if filtered.length}<div class="table"><div class="tr th"><span>Filed</span><span>Form</span><span>Report period</span><span>Accession</span><span>Primary document</span><span>Evidence</span></div>{#each filtered as row}<div class="tr"><span>{row.filingDate}</span><b>{row.form}</b><span>{row.reportDate??"—"}</span><code>{row.accessionNumber}</code><span>{row.primaryDocument??"index"}</span><a href={row.sourceUrl} target="_blank" rel="noreferrer">SEC <ExternalLink size={11}/></a></div>{/each}</div>{:else}<div class="empty"><Building2 size={30}/><strong>No governed filing observations</strong><p>Connect SEC EDGAR with a valid contact identity. Empty means unavailable—not fabricated.</p></div>{/if}
    <footer>{snapshot?`${snapshot.evidence} · ${snapshot.persistence.message}`:"SEC adapter · fair-access governor · normalized submissions"}</footer>
  </section>
</main>
<style>
  .terminal{min-height:100%;padding:clamp(18px,2.5vw,36px);overflow:auto;color:var(--p-text)}header{display:flex;justify-content:space-between;gap:22px;padding-bottom:20px;border-bottom:1px solid var(--p-border)}.eyebrow{margin:0;color:var(--p-accent);font:700 9px var(--font-mono);letter-spacing:.18em}.terminal h1{margin:8px 0 6px;font-size:clamp(28px,4vw,50px);letter-spacing:-.05em}.lede{max-width:740px;margin:0;color:var(--p-dim);line-height:1.55}.mode{display:grid;grid-template-columns:auto 1fr;align-content:center;gap:3px 8px;min-width:175px;padding:12px;border:1px solid var(--p-border);border-radius:10px;background:var(--p-panel-fill)}.mode i{grid-row:1/3;width:7px;height:7px;margin:auto;border-radius:50%;background:#f59e0b}.mode.live i{background:var(--p-up);box-shadow:0 0 10px var(--p-up)}.mode span,.mode strong{font:700 8px var(--font-mono);letter-spacing:.12em}.mode strong{color:var(--p-dim)}.controls{display:grid;grid-template-columns:1.2fr 1fr minmax(200px,1.6fr) auto;align-items:end;gap:8px;margin:16px 0}.controls label{display:grid;gap:5px;color:var(--p-dim);font:600 8px var(--font-mono);letter-spacing:.1em}.controls select,.controls input,.controls button{height:38px;padding:0 11px;border:1px solid var(--p-border);border-radius:7px;background:var(--p-panel-fill);color:var(--p-text);font:600 10px var(--font-mono)}.controls button{display:flex;align-items:center;gap:7px;color:var(--p-accent);cursor:pointer}.controls button :global(.spin){animation:spin 1s linear infinite}.notice{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;margin-bottom:12px;padding:14px;border:1px solid color-mix(in srgb,#f59e0b 38%,var(--p-border));border-radius:9px;background:var(--p-panel-fill);color:#f59e0b}.notice p{margin:4px 0 0;color:var(--p-dim);font-size:11px}.notice a{color:var(--p-accent);font:700 9px var(--font-mono)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:10px}.metrics article,.panel{border:1px solid var(--p-border);border-radius:10px;background:var(--p-panel-fill);backdrop-filter:blur(var(--p-glass-blur))}.metrics article{display:grid;gap:5px;padding:14px}.metrics span,.metrics small,.panel-head span,footer{color:var(--p-dim);font:600 8px var(--font-mono);letter-spacing:.1em}.metrics strong{overflow:hidden;font:700 18px var(--font-mono);text-overflow:ellipsis}.panel{overflow:hidden}.panel-head{display:flex;align-items:center;justify-content:space-between;padding:15px;border-bottom:1px solid var(--p-border);color:var(--p-accent)}.panel-head strong{display:block;margin-top:4px;color:var(--p-text);font:700 11px var(--font-mono)}.table{max-height:500px;overflow:auto}.tr{display:grid;grid-template-columns:.75fr .5fr .8fr 1.35fr 1.3fr .45fr;gap:10px;align-items:center;padding:10px 15px;border-bottom:1px solid var(--p-grid);font:500 9px var(--font-mono)}.tr b{color:var(--p-accent)}.tr code{overflow:hidden;text-overflow:ellipsis}.tr a{display:flex;align-items:center;gap:4px;color:var(--p-accent)}.th{position:sticky;top:0;background:var(--p-surface);color:var(--p-dim);font-size:8px;text-transform:uppercase}.empty{display:grid;place-items:center;gap:9px;padding:75px 20px;color:var(--p-dim);text-align:center}.empty strong{color:var(--p-text)}.empty p{margin:0;font-size:11px}footer{padding:12px 15px;border-top:1px solid var(--p-border)}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.controls{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:1fr 1fr}.tr{grid-template-columns:.8fr .5fr 1.3fr .4fr}.tr span:nth-child(3),.tr span:nth-child(5){display:none}}@media(max-width:620px){header{display:block}.mode{margin-top:12px}.controls{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}
</style>
